import json

def transform_v7(grid):
    """Each 1 becomes its adjacent non-0, non-1 color. Otherwise stays 1."""
    result = [row[:] for row in grid]

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 1:
                # Find adjacent colors
                neighbors = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        nval = grid[nr][nc]
                        if nval > 0 and nval != 1:
                            neighbors.append(nval)

                if neighbors:
                    # Take majority or most frequent
                    max_color = max(set(neighbors), key=neighbors.count)
                    result[r][c] = max_color

    return result

